workboard.workflowData:
{
  "1": {
    "inputs": {
      "unet_name": "{{##base_model##}}",
      "weight_dtype": "default"
    },
    "class_type": "UNETLoader",
    "_meta": {
      "title": "Anima 모델"
    }
  },
  "2": {
    "inputs": {
      "clip_name": "qwen_3_06b_base.safetensors",
      "type": "stable_diffusion",
      "device": "default"
    },
    "class_type": "CLIPLoader",
    "_meta": {
      "title": "텍스트 인코더"
    }
  },
  "3": {
    "inputs": {
      "vae_name": "qwen\\qwen_image_vae.safetensors"
    },
    "class_type": "VAELoader",
    "_meta": {
      "title": "VAE"
    }
  },
  "4": {
    "inputs": {
      "text": "masterpiece, best quality, score_7, safe, anime, {{##prompt##}}",
      "clip": [
        "2",
        0
      ]
    },
    "class_type": "CLIPTextEncode",
    "_meta": {
      "title": "긍정"
    }
  },
  "5": {
    "inputs": {
      "text": "worst quality, low quality, score_1, score_2, score_3, blurry, jpeg artifacts, sepia, mosaic, censored, {{##negative_prompt##}}",
      "clip": [
        "2",
        0
      ]
    },
    "class_type": "CLIPTextEncode",
    "_meta": {
      "title": "부정"
    }
  },
  "6": {
    "inputs": {
      "width": "{{##width##}}",
      "height": "{{##height##}}",
      "batch_size": 1
    },
    "class_type": "EmptyLatentImage",
    "_meta": {
      "title": "빈 latent"
    }
  },
  "7": {
    "inputs": {
      "seed": "{{##seed##}}",
      "steps": 30,
      "cfg": 4,
      "sampler_name": "er_sde",
      "scheduler": "simple",
      "denoise": 1,
      "model": [
        "1",
        0
      ],
      "positive": [
        "4",
        0
      ],
      "negative": [
        "5",
        0
      ],
      "latent_image": [
        "6",
        0
      ]
    },
    "class_type": "KSampler",
    "_meta": {
      "title": "샘플러"
    }
  },
  "8": {
    "inputs": {
      "samples": [
        "7",
        0
      ],
      "vae": [
        "3",
        0
      ]
    },
    "class_type": "VAEDecode",
    "_meta": {
      "title": "디코드"
    }
  },
  "9": {
    "inputs": {
      "model_name": "{{##upscale_model##}}"
    },
    "class_type": "UpscaleModelLoader",
    "_meta": {
      "title": "업스케일 모델"
    }
  },
  "10": {
    "inputs": {
      "upscale_model": [
        "9",
        0
      ],
      "image": [
        "8",
        0
      ]
    },
    "class_type": "ImageUpscaleWithModel",
    "_meta": {
      "title": "업스케일 (선택)"
    },
    "_vcc": {
      "bypassUnless": {
        "condition": "{{##upscale_model##}}",
        "passthrough": {
          "0": "image"
        }
      }
    }
  },
  "11": {
    "inputs": {
      "filename_prefix": "{{##user_id##}}\\image\\anima_t2i",
      "images": [
        "10",
        0
      ]
    },
    "class_type": "SaveImage",
    "_meta": {
      "title": "이미지 저장"
    }
  }
}
